            FfiConverterMapStringString.read(buf),
        )
    }

    override fun allocationSize(value: FfiCapability) = (
            FfiConverterString.allocationSize(value.`system`) +
            FfiConverterMapStringString.allocationSize(value.`params`)
    )

    override fun write(value: FfiCapability, buf: ByteBuffer) {
            FfiConverterString.write(value.`system`, buf)
            FfiConverterMapStringString.write(value.`params`, buf)
    }
}



