/**
 * The credentials answering one credential query.
 *
 * Complete, and independent of the `combinations` field on `FfiMatchOutcome`.
 * Callers that only need "which credentials qualify for this query" must read
 * this rather than unioning the combinations: the combination list is
 * *capped*, because its length is a product of the per-query candidate
 * counts, so a union of it can omit credentials that do qualify. Filtering on
 * such a union silently drops them from what a user is offered.
 */
data class FfiQueryMatch (
    /**
     * The DCQL credential query.
     */
    var `queryId`: kotlin.String, 
    /**
     * Every credential that satisfies it.
     */
    var `credentials`: List<FfiMatchedCredential>
) {
    
    companion object
}

/**
 * @suppress
 */
public object FfiConverterTypeFfiQueryMatch: FfiConverterRustBuffer<FfiQueryMatch> {
    override fun read(buf: ByteBuffer): FfiQueryMatch {
        return FfiQueryMatch(
            FfiConverterString.read(buf),
            FfiConverterSequenceTypeFfiMatchedCredential.read(buf),
        )
    }

    override fun allocationSize(value: FfiQueryMatch) = (
            FfiConverterString.allocationSize(value.`queryId`) +
            FfiConverterSequenceTypeFfiMatchedCredential.allocationSize(value.`credentials`)
    )

    override fun write(value: FfiQueryMatch, buf: ByteBuffer) {
            FfiConverterString.write(value.`queryId`, buf)
            FfiConverterSequenceTypeFfiMatchedCredential.write(value.`credentials`, buf)
    }
}





/**
 * Why a blob could not be built.
 */
sealed class BlobException: kotlin.Exception() {
    
    /**
     * The credential set could not be encoded.
     */
    class Encoding(
        
        /**
         * What went wrong.
         */
        val `reason`: kotlin.String
        ) : BlobException() {
        override val message
            get() = "reason=${ `reason` }"
    }
    
    /**
     * A credential referred to an icon that was never added.
     */
    class UnknownIcon(
        
        /**
         * The credential holding the dangling reference.
         */
        val `credentialId`: kotlin.String, 
        
        /**
         * The icon it asked for.
         */
        val `iconId`: kotlin.String
        ) : BlobException() {
        override val message
            get() = "credentialId=${ `credentialId` }, iconId=${ `iconId` }"
    }
    

    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<BlobException> {
        override fun lift(error_buf: RustBuffer.ByValue): BlobException = FfiConverterTypeBlobError.lift(error_buf)
    }

    
}

/**
 * @suppress
 */
public object FfiConverterTypeBlobError : FfiConverterRustBuffer<BlobException> {
    override fun read(buf: ByteBuffer): BlobException {
        

        return when(buf.getInt()) {
            1 -> BlobException.Encoding(
                FfiConverterString.read(buf),
                )
            2 -> BlobException.UnknownIcon(
                FfiConverterString.read(buf),
                FfiConverterString.read(buf),
                )
            else -> throw RuntimeException("invalid error enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: BlobException): ULong {
        return when(value) {
            is BlobException.Encoding -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`reason`)
            )
            is BlobException.UnknownIcon -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`credentialId`)
                + FfiConverterString.allocationSize(value.`iconId`)
            )
        }
    }

    override fun write(value: BlobException, buf: ByteBuffer) {
        when(value) {
            is BlobException.Encoding -> {
                buf.putInt(1)
                FfiConverterString.write(value.`reason`, buf)
                Unit
            }
            is BlobException.UnknownIcon -> {
                buf.putInt(2)
                FfiConverterString.write(value.`credentialId`, buf)
                FfiConverterString.write(value.`iconId`, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }

}





/**
 * Why a request could not be matched.
 */
sealed class MatchException: kotlin.Exception() {
    
    /**
     * The registered blob could not be decoded.
     */
    class Blob(
        
        /**
         * What went wrong.
         */
        val `reason`: kotlin.String
        ) : MatchException() {
        override val message
            get() = "reason=${ `reason` }"
    }
    
    /**
     * The request was not valid JSON, or not shaped like a request.
     */
    class Request(
        
        /**
         * What went wrong.
         */
        val `reason`: kotlin.String
        ) : MatchException() {
        override val message
            get() = "reason=${ `reason` }"
    }
    
    /**
     * No protocol in the request is one this wallet can read.
     *
     * Distinct from "nothing matched": the wallet may hold exactly what was
     * asked for and still be unable to speak the protocol it was asked in.
     *
     * Carries what was offered, because a variant with no fields loses its
     * message crossing the boundary — UniFFI renders it as the case name
     * alone, so a host app logging the error would learn nothing about why.
     * The protocols the verifier named are the one thing that makes this
     * actionable.
     */
    class UnsupportedProtocol(
        
        /**
         * The protocols the request offered, in the order given.
         */
        val `offered`: List<kotlin.String>
        ) : MatchException() {
        override val message
            get() = "offered=${ `offered` }"
    }
    

    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<MatchException> {
        override fun lift(error_buf: RustBuffer.ByValue): MatchException = FfiConverterTypeMatchError.lift(error_buf)
    }

    
}

/**
 * @suppress
 */
public object FfiConverterTypeMatchError : FfiConverterRustBuffer<MatchException> {
    override fun read(buf: ByteBuffer): MatchException {
        

        return when(buf.getInt()) {
            1 -> MatchException.Blob(
                FfiConverterString.read(buf),
                )
            2 -> MatchException.Request(
                FfiConverterString.read(buf),
                )
            3 -> MatchException.UnsupportedProtocol(
                FfiConverterSequenceString.read(buf),
                )
            else -> throw RuntimeException("invalid error enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: MatchException): ULong {
        return when(value) {
            is MatchException.Blob -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`reason`)
            )
            is MatchException.Request -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`reason`)
            )
            is MatchException.UnsupportedProtocol -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterSequenceString.allocationSize(value.`offered`)
            )
        }
    }

    override fun write(value: MatchException, buf: ByteBuffer) {
        when(value) {
            is MatchException.Blob -> {
                buf.putInt(1)
                FfiConverterString.write(value.`reason`, buf)
                Unit
            }
            is MatchException.Request -> {
                buf.putInt(2)
                FfiConverterString.write(value.`reason`, buf)
                Unit
            }
            is MatchException.UnsupportedProtocol -> {
                buf.putInt(3)
                FfiConverterSequenceString.write(value.`offered`, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }

}





/**
 * Why a `zkp_req` query could not be planned.
 */
sealed class ZkpReqPlanException: kotlin.Exception() {
    
    /**
     * The query is structurally broken: the planner's verdict, unchanged.
     *
     * This says the request is malformed, never that it cannot be served.
     */
    class InvalidRequest(
        
        /**
         * A stable identifier for the defect, the planner's own code:
         * `query_not_parseable`, `req_missing_or_empty`, `req_ambiguous`,
         * `item_missing_function_id`, `item_missing_handle`,
         * `param_wrong_type`, `param_invalid_full_date`, `duplicate_handle`,
         * `claims_present`, `claim_sets_present`, `req_sets_present`,
         * `invalid_meta` or `invalid_client_metadata`. Match on this, not on
         * `reason`.
         */
        val `code`: kotlin.String, 
        
        /**
         * The planner's message, for logs. Its wording may change.
         */
        val `reason`: kotlin.String
        ) : ZkpReqPlanException() {
        override val message
            get() = "code=${ `code` }, reason=${ `reason` }"
    }
    

    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<ZkpReqPlanException> {
        override fun lift(error_buf: RustBuffer.ByValue): ZkpReqPlanException = FfiConverterTypeZkpReqPlanError.lift(error_buf)
    }

    
}

